func run() -> int:
	var variables: Dictionary = {"has_lantern": false, "bravery": 10}
	var condition: Dictionary = {"variable": "has_lantern", "operator": "==", "value": true}
	var current: Variant = variables.get(condition["variable"], null)
	if current == condition["value"]:
		variables["bravery"] = variables.get("bravery", 0) + 15
	else:
		variables["bravery"] = variables.get("bravery", 0) + 5
	return variables.get("bravery", 0)

